<template><div><Navbar/><main>
  <section class="hero shell"><div class="hero-copy"><span>PRE-LOVED · WELL-CHOSEN</span><h1>Find something<br><em>worth keeping.</em></h1><p>Clear condition notes, fair prices and protected checkout on every carefully selected piece.</p><div class="hero-actions"><router-link to="/browse">Browse all products <b>→</b></router-link><router-link class="text" to="/browse?sort=discount">See current offers</router-link></div><div class="proof"><span><b>✓</b> Quality checked</span><span><b>✓</b> Buyer protection</span><span><b>✓</b> EU delivery</span></div></div><div class="hero-visual"><div class="visual-card"><span>FRESH FIND</span><img v-if="heroProduct?.images?.[0]" :src="heroProduct.images[0].image_url||heroProduct.images[0].thumbnail_url" :alt="heroProduct.title_en||heroProduct.title"/><div><p>{{ heroProduct?.brand||'CURATED THIS WEEK' }}</p><strong>{{ heroProduct?.title_en||heroProduct?.title||'Thoughtful finds, ready for a new home' }}</strong><em v-if="heroProduct">€{{ money(heroProduct.sale_price) }}</em></div></div></div></section>
