  </main><Footer/></div></template>
<script setup>
import { computed,onBeforeUnmount,onMounted,ref } from 'vue';import Navbar from '../components/Navbar.vue';import Footer from '../components/Footer.vue';import ProductCard from '../components/ProductCard.vue';import { getProducts } from '../api'
const products=ref([]),total=ref(0),page=ref(1),loading=ref(true),loadingMore=ref(false),sentinel=ref(null);const pageSize=12;let observer
const heroProduct=computed(()=>products.value[0]);const money=v=>Number(v||0).toFixed(2)
async function load(next=false){if(next&&(loadingMore.value||products.value.length>=total.value))return;next?loadingMore.value=true:loading.value=true;try{const {data}=await getProducts({page:next?page.value+1:1,page_size:pageSize,sort:'new'});const incoming=data.items||[];products.value=next?[...products.value,...incoming.filter(x=>!products.value.some(p=>p.id===x.id))]:incoming;total.value=Number(data.total||products.value.length);if(next)page.value++}finally{loading.value=false;loadingMore.value=false}}
onMounted(async()=>{await load();observer=new IntersectionObserver(entries=>{if(entries[0].isIntersecting)load(true)},{rootMargin:'500px'});if(sentinel.value)observer.observe(sentinel.value)})
onBeforeUnmount(()=>observer?.disconnect())
</script>
